contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 x) public {
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceBefore = c.balanceOf(owner); if (__ESBMC_reverted()) return;
        require(x <= ownerBalanceBefore, "x must not exceed owner's balance");

        bool reverted;
        bool success;
        bool s = c.burn(x); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            success = s;
            reverted = false;
        }

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceAfter = c.balanceOf(owner); if (__ESBMC_reverted()) return;

        assert(!reverted && success && ownerBalanceAfter == ownerBalanceBefore - x && supplyAfter == supplyBefore - x);
    }
}

